import {api,segment} from './api.js';
import {icon,esc,attr,link,button,state,errorState,loader,compactDate,compactTime,pic,pretty,fields,tile,initials} from './ui.js';
import {doctorClinicalHub,doctorClinicalCase,patientAssistant,chatView} from './clinical-demo.js';
import {guestPage} from './guest-assessments.js';
export {guestPage} from './guest-assessments.js';
export const roleHomes={patient:'/patient',doctor:'/doctor',clinic_admin:'/clinic',platform_admin:'/clinic',researcher:'/research'};
export const roleNames={patient:'Пациент',doctor:'Врач',clinic_admin:'Администратор клиники',platform_admin:'Администратор',researcher:'Исследователь'};
export const nav={
 patient:[['Сегодня','/patient','heart'],['Задания','/patient/tasks','clipboard'],['AI-чат','/patient/assistant','spark'],['Динамика','/patient/trends','chart'],['Лечение','/patient/treatment','activity'],['Приёмы','/patient/appointments','calendar'],['Обращения','/patient/requests','mail'],['Сообщения','/patient/messages','message'],['Мои специалисты','/patient/specialists','users'],['Доступ','/patient/access','shield'],['Профиль','/patient/profile','user']],
 doctor:[['Рабочий стол','/doctor','chart'],['Пациенты','/doctor/patients','users'],['Сигналы','/doctor/alerts','activity'],['Обращения','/doctor/requests','mail'],['Приёмы','/doctor/appointments','calendar'],['Сообщения','/doctor/messages','message'],['Опросники','/doctor/questionnaires','clipboard'],['Приглашения','/doctor/invitations','plus'],['Клиническая база','/doctor/clinical-library','book'],['Коллеги','/doctor/colleagues','users'],['Помощник','/doctor/clinical-copilot','spark'],['Профиль','/doctor/profile/edit','user']],
 clinic_admin:[['Обзор','/clinic','chart'],['Запись','/clinic/appointments','calendar'],['Пациенты','/clinic/patients','users'],['Сотрудники','/clinic/staff','user'],['Приглашения','/clinic/invitations','mail'],['Доступ','/clinic/access-templates','shield'],['Аудит','/clinic/audit','file']],
 researcher:[['Обзор','/research','chart'],['Датасеты','/research/datasets','file'],['Когорты','/research/cohorts','users'],['Сравнение','/research/compare','chart'],['Сигналы','/research/signals','activity'],['Экспорт','/research/exports','upload'],['Демо-данные','/research/demo-v3','flask']]
};nav.platform_admin=nav.clinic_admin;
const card=(body,cls='')=>`<section class="card ${cls}">${body}</section>`;
const roleTile=(heading,description,iconName)=>`<article class="action-tile role-tile"><div class="tile-icon">${icon(iconName)}</div><div><h3>${esc(heading)}</h3><p>${esc(description)}</p></div></article>`;
const notice=(msg,warning=false)=>`<div class="notice ${warning?'warning':''}">${esc(msg)}</div>`;
const title=(header,descr='',back='')=>`<div class="crumbs">${back?`<a href="/#${attr(back)}">${icon('left',14)} Назад</a> · `:''}<a href="/#/">Clinical Compass</a></div><h1 class="page-title">${esc(header)}</h1>${descr?`<p class="page-intro">${esc(descr)}</p>`:''}`;
const list=(items,render,empty='Данных пока нет',desc='Новые записи появятся здесь после подтверждения на сервере.')=>items?.length?items.map(render).join(''):state(empty,desc);
const row=(head,sub,href,tag='Открыть',pill='')=>`<div class="list-row"><div class="row-main"><h4>${esc(head)}</h4><div class="sub">${esc(sub)}</div></div>${pill?`<span class="pill">${esc(pill)}</span>`:''}${href?link(href,tag,'secondary'):''}</div>`;
const cards=(items,mapper)=>`<div class="columns three">${items.map(mapper).join('')}</div>`;
const err=async(f)=>{try{return {data:await f()}}catch(e){return {error:e}}};
const protectedError=(e)=>card(errorState(e));
const safeArray=(x)=>Array.isArray(x)?x:[];
const apiPath=(template,params={})=>template.replace(/:([A-Za-z]+)/g,(_,k)=>segment(params[k]??''));
const status=(str)=>({submitted:'Отправлено',reviewed:'Рассмотрено',assigned:'Назначено',pending:'Ожидает',accepted:'Принято',confirmed:'Подтверждено',offered:'Предложено',active:'Активно',completed:'Выполнено',acknowledged:'Подтверждено',open:'Открыто',closed:'Закрыто'})[str]||str||'—';
const allowed=(app,role)=>!role||role==='shared'||(app.session?.context?.role===role)||(role==='clinic'&&['clinic_admin','platform_admin'].includes(app.session?.context?.role));
const doctorImg=(d,large=false)=>pic(d,large);

export function chrome(session,env,active){
  const role=session?.context?.role;
  const opts=nav[role]||[];
  const links=(role&&opts.length)?`<nav class="section-nav" aria-label="Разделы кабинета"><div class="nav-caption">Навигация</div>${opts.map(([l,p,i])=>`<a href="/#${attr(p)}" class="${(active===p||active.startsWith(p+'/')&&p!==roleHomes[role])?'active':''}">${icon(i)}${esc(l)}</a>`).join('')}</nav>`:'';
  const demo=['synthetic_dev','evaluation_sandbox'].includes(env);
  const menu=session?`<div class="header-menu-anchor"><button type="button" class="avatar" data-command="menu" id="avatar-button" aria-haspopup="menu" aria-expanded="false" aria-label="Открыть меню аккаунта">${esc(initials(session.user?.display_name))}</button><div id="account-menu-holder"></div></div>`:`<a class="btn btn-quiet" href="/#/login">Войти</a><a class="btn btn-primary" href="/#/register">Регистрация</a>`;
  const brandDestination=session?(roleHomes[role]||'/'):'/';
  const brandLabel=session?'кабинет':'главная';
  const head=`<header class="topbar-wrap"><div class="shell topbar"><a class="brand" href="/#${attr(brandDestination)}" aria-label="Clinical Compass — ${brandLabel}"><span class="brand-mark">${icon('compass',22)}</span><span class="brand-word">Clinical Compass</span>${demo?'<span class="brand-demo">Демо</span>':''}</a><div class="header-right"><a class="btn btn-quiet header-library" href="/#/clinical-library">Справочник</a>${menu}</div></div></header>`;
  return {head,aside:links,footer:`<footer class="footer"><div class="shell"><span>© Clinical Compass · Учебная и оценочная платформа</span><span>Не предназначено для экстренной медицинской помощи</span></div></footer>`};
}
export function accountMenu(session,env){let role=session.context.role,opts=[];
 if(role==='doctor')opts.push(['Пригласить пациента','/doctor/invitations/new','plus']);
 else if(role==='clinic_admin'||role==='platform_admin')opts.push(['Пригласить сотрудника','/clinic/invitations','plus']);
 else opts.push(['Принять приглашение','/invite/accept','mail']);
 opts.push(['Уведомления','/notifications','bell'],['Настройки','modal:settings','settings']);
 if(['doctor','patient'].includes(role))opts.push(['Мой профиль',role==='doctor'?'/doctor/profile/edit':'/patient/profile','user']);
 return `<div class="account-menu" role="menu" aria-label="Меню аккаунта"><div class="account-summary"><strong>${esc(session.user.display_name)}</strong><div class="small muted">${esc(roleNames[role]||role)}</div></div>${opts.map(([l,p,i])=>p.startsWith('modal:')?`<button class="menu-item" role="menuitem" data-command="settings">${icon(i)} ${esc(l)}</button>`:`<a role="menuitem" class="menu-item" href="/#${attr(p)}">${icon(i)} ${esc(l)}</a>`).join('')}<button type="button" class="menu-item danger" role="menuitem" data-command="logout">${icon('logout')} Выйти</button></div>`;}
export function landing(app){return `<section class="hero"><h1>Лечение не ограничивается сеансами</h1><p class="lead">Пространство, где пациент, специалист и команда клиники находятся на связи.</p><div class="columns hero-actions">${tile('Найти специалиста','Откройте каталог и изучите опубликованные сведения о врачах.','/doctors','search','Найти врача')}${tile('Войти по приглашению','Проверьте, кто приглашает вас к наблюдению и к каким данным запрашивается доступ.','/invite/accept','shield','Открыть приглашение')}</div></section><section class="section"><div class="section-heading"><div><h2>Продуманная связь и ясные границы</h2><p class="muted reading">Каждое действие и разрешение подтверждается сервером. Доступ к медицинской информации зависит от конкретных согласий.</p></div></div><div class="columns three">${roleTile('Пациенту','Задания, опросники, динамика состояния, записи на приём и сообщения специалистам — в одном кабинете.','heart')}${roleTile('Специалисту','Доступ к согласованным данным пациентов, обращениям, сигналам и инструментам сопровождения — в одном интерфейсе.','clipboard')}${roleTile('Исследователю','Анализ синтетических наборов данных: когорты, сравнение показателей, сигналы и экспорт агрегатов.','flask')}</div></section><section class="section">${card(`<div class="row space-between"><div><p class="eyebrow">Учебный контур</p><h2 class="max-width-600">Содержимое платформы — не замена клинического решения</h2><p class="reading">Демонстрационные данные и исследовательские инструменты предназначены для проверки пользовательских сценариев. Не вводите реальные персональные или медицинские данные.</p></div>${link('/assessments','Пройти PHQ-9 / PHQ-2 / GAD-7 / GAD-2','secondary','clipboard')}${link('/demo/journeys','Сценарии всех ролей','secondary','chart')}${link('/register','Регистрация','primary','arrow')}</div>`,'graphite-feature')}</section>`;}
export function authPage(path,app){const patient=path==='/register/patient';const specialist=path==='/register/specialist';const login=path==='/login';const enabled=app.bootstrap?.boot?.enabled,oidc=app.bootstrap?.oidc?.enabled;
 if(path==='/register')return `<div class="auth-wrap">${title('Присоединиться','Выберите способ подключения к платформе.')}<div class="stack">${tile('Я пациент','Самостоятельная регистрация доступна только в разрешённой синтетической среде.','/register/patient','heart','Продолжить')}${tile('Я специалист','Врачебная роль создаётся по приглашению организации, не через свободную регистрацию.','/register/specialist','user','Узнать условия')}</div></div>`;
 if(specialist)return `<div class="auth-wrap">${title('Подключение специалиста','Регистрация врача осуществляется только через подтверждённое приглашение.')} ${card(`${notice('Самостоятельная выдача врачебной роли недоступна. Попросите администратора организации отправить приглашение.',true)}<div class="row space-top-20">${link('/invite/accept','У меня есть приглашение','primary','mail')}${link('/login','Уже есть аккаунт','secondary')}</div>`)}</div>`;
 if(login)return `<div class="auth-wrap">${title('С возвращением','Войдите, чтобы продолжить работу.')} ${card(`<form class="form-stack" data-form="login"><div class="field"><label for="login-email">Email</label><input id="login-email" name="email" type="email" autocomplete="username" placeholder="example@evaluation.test" required maxlength="254"></div><div class="field"><label for="login-pass">Пароль</label><input id="login-pass" name="password" type="password" autocomplete="current-password" placeholder="Введите пароль" required></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary" ${!enabled?'disabled':''}>${icon('lock')} Войти</button>${!enabled?notice('Локальный вход выключен в этой среде. Используйте разрешённый серверный способ аутентификации.',true):''}</form>${oidc?`<div class="divider-text space-block-24">или</div><a class="btn btn-secondary full-width" href="/api/v1/auth/oidc/login?return_to=%2F">Войти через организацию</a>`:''}<div class="grid-line"></div><div class="row space-between"><span class="small muted">Нет аккаунта?</span>${link('/register','Зарегистрироваться')}</div>`)}</div>`;
 return `<div class="auth-wrap">${title('Регистрация пациента','Пошаговая регистрация в разрешённой синтетической среде.')} ${card(`<form data-form="register" class="form-stack" id="register-form"><div class="steps" aria-label="Шаг регистрации"><span class="done"></span><span></span></div><div data-wizard="1"><h3>Личные данные</h3><div class="field"><label for="reg-name">Как к вам обращаться</label><input id="reg-name" name="display_name" autocomplete="name" placeholder="Имя и фамилия" minlength="2" maxlength="100" required></div><div class="field"><label for="reg-email">Email (.test или .example)</label><input id="reg-email" name="email" type="email" autocomplete="email" placeholder="patient@example.test" required></div><button type="button" class="btn btn-primary" data-command="next-registration">Продолжить ${icon('arrow')}</button></div><div data-wizard="2" hidden><h3>Доступ и согласие</h3><div class="field"><label for="reg-pass">Пароль — от 12 символов</label><input id="reg-pass" name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" placeholder="Придумайте пароль" required></div><div class="field"><label for="reg-pass2">Повторите пароль</label><input id="reg-pass2" name="confirm_password" type="password" minlength="12" maxlength="128" autocomplete="new-password" placeholder="Повторите пароль" required></div><label class="checkline"><input name="terms_consent" type="checkbox" required><span>Я понимаю, что это синтетическая среда, и согласен(на) с условиями её использования.</span></label><div class="row"><button type="button" class="btn btn-quiet" data-command="back-registration">${icon('left')} Назад</button><button class="btn btn-primary" ${!enabled?'disabled':''}>Создать аккаунт</button></div></div><p class="error-inline" data-form-error role="alert"></p>${!enabled?notice('Регистрация выключена конфигурацией сервера.',true):''}</form>`)}</div>`;
}
export function invitationPage(token,app){return `${title('Принять приглашение','Права доступа раскрываются только после проверки токена приглашения.','/')} ${card(`<form class="form-stack" data-form="invite-preview"><div class="field"><label for="invite-token">Код или ссылка приглашения</label><input name="token" id="invite-token" required value="${attr(token||'')}" placeholder="Введите код или вставьте ссылку"></div><div class="row"><button class="btn btn-primary">${icon('search')} Проверить приглашение</button>${link('/register/patient','Регистрация пациента')}</div><p class="error-inline" data-form-error role="alert"></p></form><div id="invitation-preview" class="space-top-20"></div>`)}`;}
export async function publicDoctors(path,params,app){
 if(path==='/doctors'){const r=await err(()=>api.get('/api/v1/public/doctors'));if(r.error)return title('Каталог специалистов','Опубликованные профили специалистов')+protectedError(r.error);
 const docs=safeArray(r.data.items);return `${title('Найти специалиста','Просмотрите опубликованные профили. Сведения о квалификации могут быть не проверены.')}<div class="search-tools"><input type="search" aria-label="Поиск по имени или специальности" class="search-field" id="doctor-search" placeholder="Поиск по имени или специальности"></div><div id="doctor-grid" class="columns three">${docs.length?docs.map(d=>doctorCard(d)).join(''):state('Специалисты пока не опубликованы','В каталоге появятся профили после подтверждённой публикации.')}</div>`;}
 const slug=params.slug;const r=await err(()=>api.get(`/api/v1/public/doctors/${segment(slug)}`));
 if(r.error?.status===404&&app.session?.context?.role==='patient'&&!path.endsWith('/share')&&!path.endsWith('/reviews')){
  const own=await err(()=>api.get('/api/v1/patients/me/links'));
  const linked=safeArray(own.data?.items).find(d=>d.id===slug);
  if(linked)return title('Ваш специалист','Сведения из подтверждённой связи; это не публичный профиль.','/patient/specialists')+card(`<h2>${esc(linked.display_name)}</h2><p>${esc(linked.specialty||'Специальность не указана')}</p>${notice('Принятое приглашение не подтверждает профессиональные полномочия. Публичные сведения о квалификации проверяются отдельно.')}<div class="row">${link('/patient/requests/new?doctor='+segment(linked.id),'Подготовить обращение','primary')}${link('/patient/specialists','Мои специалисты','secondary')}</div>`);
 }
 if(r.error)return title('Профиль врача','', '/doctors')+protectedError(r.error);const d=r.data;
 if(path.endsWith('/share'))return `${title('Поделиться профилем','',`/doctors/${segment(slug)}`)}${card(`<p class="muted">Скопируйте ссылку на опубликованный профиль.</p><div class="row"><code class="chip break-anywhere" id="share-url">${esc(location.origin+'/#/doctors/'+segment(slug))}</code><button class="btn btn-primary" data-command="copy-link">${icon('copy')} Скопировать</button></div>`)}`;
 if(path.endsWith('/reviews'))return `${title('Отзывы','',`/doctors/${segment(slug)}`)}${card(list(d.reviews||[],r=>row(r.title||'Отзыв',r.text||'',null),'Опубликованных отзывов нет','Рейтинг и отзывы не формируются из вымышленных данных.'))}`;
 const desc=esc(d.bio||'Специалист не добавил описание.');return `${title('Профиль специалиста','', '/doctors')} ${card(`<div class="row row-align-top"><div>${doctorImg(d,true)}</div><div class="grow"><h2>${esc(d.name||'Специалист')}</h2><p class="muted">${esc(d.specialty_label||d.specialty||'Специальность не указана')}</p><div class="row"><span class="pill">${esc(d.verified==='synthetic_demo'?'Демонстрационные сведения':'Сведения профиля')}</span>${d.experience_years!=null?`<span class="pill">${esc(d.experience_years)} лет опыта (по данным профиля)</span>`:''}</div></div></div><div class="grid-line"></div><p>${desc}</p>${d.qualification_notice?notice(d.qualification_notice,true):''}<div class="row space-top-20">${app.session?.context?.role==='patient'?`<a class="btn btn-primary" href="/#/patient/requests/new?doctor=${attr(d.id)}">${icon('mail')} Подготовить обращение</a>`:link('/login','Обратиться к врачу','primary','mail')}${link(`/doctors/${segment(slug)}/share`,'Поделиться','secondary','copy')}${link(`/doctors/${segment(slug)}/reviews`,'Отзывы')}</div>`)}`+
 (safeArray(d.education).length?card(`<h3>Образование</h3>${safeArray(d.education).map(e=>row(e.institution||'Образование',[e.specialization,e.year_to].filter(Boolean).join(' · '))).join('')}`):'')+
 (safeArray(d.certificates).length?card(`<h3>Сертификаты</h3>${safeArray(d.certificates).map(e=>row(e.title||'Сертификат',e.issuer||'')).join('')}`):'')+
 (safeArray(d.publications).length?card(`<h3>Публикации</h3>${safeArray(d.publications).map(e=>row(e.title||'Публикация',e.journal||'')).join('')}`):'')+
 (app.session?.context?.role==='doctor'?card(`<h3>Общие пациенты</h3><p class="muted">Персональные связи показываются только при подтверждённых разрешениях.</p><a class="btn btn-secondary" href="/#/doctor/colleagues/${segment(d.id)}/shared-patients">Проверить доступ</a>`):'');
}
export function doctorCard(d){const p=`/doctors/${segment(d.slug||d.id)}`;return `<article class="card slim"><div class="doctor-head">${doctorImg(d)}<div><h3>${esc(d.name||'Специалист')}</h3><div class="small muted">${esc(d.specialty_label||d.specialty||'')}</div></div></div><p class="small muted space-block-17">${esc((d.bio||'').slice(0,145)||'Откройте профиль для подробных сведений.')}</p><a class="btn btn-secondary" href="/#${attr(p)}">Подробнее ${icon('arrow')}</a></article>`;}
function chartSeries(series,period=30){
  const items=safeArray(series).filter(s=>safeArray(s.points).length);
  if(!items.length)return state('Недостаточно наблюдений','После сохранения наблюдений или ответов здесь появится динамика.');
  return items.map(s=>{
    const pts=safeArray(s.points).filter(p=>Number.isFinite(Number(p.value))&&p.observed_at).sort((a,b)=>String(a.observed_at).localeCompare(String(b.observed_at)));
    const cutoff=Date.now()-period*86400000;const selected=pts.filter(p=>new Date(p.observed_at).getTime()>=cutoff);
    if(!selected.length)return card(`<h3>${esc(s.label||'Показатель')}</h3>${state('Нет данных за выбранный период','Попробуйте другой интервал.')}`);
    const min=Math.min(...selected.map(p=>Number(p.value))),max=Math.max(...selected.map(p=>Number(p.value))),span=Math.max(1,max-min);
    const dots=selected.map((p,i)=>{let x=40+(selected.length===1?240:i*520/(selected.length-1));let y=185-(Number(p.value)-min)/span*140;return {x,y,p};});
    const poly=dots.map(pt=>`${pt.x},${pt.y}`).join(' ');
    return card(`<div class="row space-between"><h3>${esc(s.label||'Показатель')}</h3><span class="pill">${esc(s.unit||'')}</span></div><svg class="chart" viewBox="0 0 600 225" preserveAspectRatio="xMidYMid meet" role="img" aria-label="График: ${attr(s.label||'Показатель')}, ${selected.length} измерений">${[50,100,150,185].map(y=>`<line class="chart-grid" x1="40" y1="${y}" x2="570" y2="${y}"/>`).join('')}<polyline class="chart-line" points="${poly}"/>${dots.map(({x,y,p})=>`<circle class="chart-dot" cx="${x}" cy="${y}" r="5"><title>${esc(compactTime(p.observed_at))}: ${esc(p.value)}</title></circle>`).join('')}<text class="chart-label" x="40" y="211">${esc(compactDate(selected[0].observed_at))}</text><text class="chart-label" x="570" y="211" text-anchor="end">${esc(compactDate(selected.at(-1).observed_at))}</text></svg><p class="small muted">Источник: ${esc([...new Set(selected.map(p=>p.source||'сервер'))].join(', '))}. ${selected.length} точек. Статистическая интерпретация не выполняется.</p>`);
  }).join('');
}
export async function patientPage(path,params,app){
 const r=app.session?.context?.role;if(r!=='patient')return `${title('Доступ ограничен')}${card(state('Нужен кабинет пациента','Этот раздел доступен только авторизованному пациенту.','forbidden',link('/login','Войти','primary')))}`;
 const p='/api/v1/patient-experience';
 if(path==='/patient'){
  const res=await err(()=>api.get(p+'/dashboard'));
  if(res.error)return title('Мой день')+protectedError(res.error);
  const d=res.data;
  const checkinCard=card(`<p class="eyebrow">Ваше самочувствие</p><h2>Как вы сегодня?</h2><p class="muted">Отметка от 1 до 5 сохранится только после ответа сервера.</p><form data-form="checkin" class="form-stack"><fieldset class="bare-fieldset"><legend class="small muted space-bottom-12">Выберите оценку</legend><div class="row">${[1,2,3,4,5].map(n=>`<label class="chip"><input name="mood_score" value="${n}" type="radio" required> ${n}</label>`).join('')}</div></fieldset><div class="field"><label for="mood-compare">По сравнению с прошлым разом</label><select id="mood-compare" name="comparison" required><option value="" selected disabled>Выберите вариант</option><option value="better">Лучше</option><option value="same">Так же</option><option value="worse">Хуже</option><option value="unsure">Трудно сказать</option></select></div><div class="field"><label for="mood-note">Комментарий</label><textarea id="mood-note" name="note" maxlength="2000" placeholder="Можно оставить пустым"></textarea></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">${icon('check')} Сохранить отметку</button></form>`);
  const tasksCard=card(`<div class="row space-between"><div><p class="eyebrow">Назначенные задания</p><h2>Опросники</h2></div>${link('/patient/tasks','Все задания')}</div>${list(safeArray(d.assignments).slice(0,4),a=>row(a.definition_id||'Опросник',status(a.status),`/patient/questionnaires/${segment(a.id)}`),'Заданий пока нет')}`);
  const trendCard=card(`<div class="row space-between"><h2>Динамика</h2>${link('/patient/trends','Подробнее')}</div>${chartSeries(safeArray(d.series).slice(0,1),30)}`);
  const visitsCard=card(`<h3>Ближайшие приёмы</h3>${list(safeArray(d.appointments),a=>row(compactTime(a.proposed_at),status(a.status),'/patient/appointments'),'Подтверждённых приёмов нет')}${link('/patient/appointments','Перейти к приёмам','secondary','calendar')}`);
  const linksCard=card(`<h3>Мои специалисты</h3>${list(safeArray(d.links),v=>row(v.display_name,v.specialty||'',`/doctors/${segment(v.id)}`),'Наблюдающих специалистов пока нет')}${link('/doctors','Найти врача','secondary','search')}`);
  const extrasCard=card(`<h3>Другие разделы</h3>${nav.patient.slice(3,9).map(([l,href])=>row(l,'',href)).join('')}`);
  return `${title('Добрый день'+(d.patient?.display_name?', '+d.patient.display_name:''),'Здесь — важные действия и подтверждённая информация о вашем сопровождении.')}<div class="dashboard-grid section"><div class="stack">${checkinCard}${tasksCard}${trendCard}</div><div class="stack">${visitsCard}${linksCard}${extrasCard}</div></div>`;
 }
 if(path==='/patient/tasks'){
  const responses=await Promise.allSettled([api.get(p+'/questionnaires/assignments'),api.get(p+'/questionnaires/definitions')]);
  const assignments=responses[0].status==='fulfilled'?responses[0].value:null;
  const definitions=responses[1].status==='fulfilled'?responses[1].value:null;
  const evalDefs=safeArray(definitions?.items).filter(x=>x.status==='evaluation_draft_unapproved');
  const actions=evalDefs.length?card(`<h2>Опросники для тестирования</h2>${notice('Русскоязычные версии ещё не утверждены для клинического применения. Проходите только на вымышленных данных; результаты не являются диагнозом.',true)}${evalDefs.map(d=>`<div class="list-row"><div class="row-main"><h4>${esc(d.title)}</h4><p class="small muted">${esc(d.questions?.length||0)} вопросов · итоговая сумма ${esc(d.min_score)}–${esc(d.max_score)}</p></div><button type="button" class="btn btn-secondary btn-sm" data-command="start-assessment" data-id="${attr(d.id)}">Пройти</button></div>`).join('')}`):'';
  return title('Мои задания','Сохранённые результаты и доступные формы для оценки интерфейса.', '/patient')+
   actions+(assignments?card(`<h2>Мои прохождения</h2>${list(assignments.items,a=>row(safeArray(definitions?.items).find(d=>d.id===a.definition_id)?.title||a.definition_id,`Статус: ${status(a.status)} · ${compactDate(a.created_at)}`,`/patient/questionnaires/${segment(a.id)}${a.status==='submitted'?'/result':''}`,a.status==='submitted'?'Посмотреть результат':'Продолжить'),'Назначений пока нет','Можно запустить учебный опросник выше.')}`):protectedError(responses[0].reason));
 }
 if(path.startsWith('/patient/questionnaires/')){
  const aid=params.requestId,base=p+'/questionnaires/assignments/'+segment(aid);
  if(path.endsWith('/result')){
   const r=await err(()=>api.get(base+'/result'));
   return title('Результат опросника','', '/patient/tasks')+(r.error?protectedError(r.error):card(`<p class="eyebrow">${r.data.evaluation_draft?'Результат пилотной формы':'Результат технической формы'}</p><h2>${esc(r.data.title||'Опросник')}</h2><h2>${esc(r.data.score)} из ${esc(r.data.max_score)} баллов</h2><p class="small muted">Возможный диапазон: ${esc(r.data.min_score)}–${esc(r.data.max_score)} · ${esc(compactDate(r.data.submitted_at))}</p>${notice(r.data.disclaimer||'Без клинической интерпретации.',true)}<p>${esc(r.data.technical_note||'')}</p><h3>Ответы</h3>${safeArray(r.data.answers).map(a=>row(a.label,`${a.answer_label||a.value} · ${a.value} балл(ов)`)).join('')}${link('/patient/tasks','К другим опросникам','secondary')}`));
  }
  const r=await err(()=>api.get(base));if(r.error)return title('Опросник','', '/patient/tasks')+protectedError(r.error);
  const d=r.data,questions=safeArray(d.definition?.questions),answers=d.draft?.answers||{};
  if(d.assignment?.status==='submitted')return title('Опросник заполнен')+card(state('Ответы отправлены','Форма уже принята сервером.','empty',link(`/patient/questionnaires/${segment(aid)}/result`,'Посмотреть результат','primary')));
  const clinicalDraft=d.definition?.status==='evaluation_draft_unapproved';
  return `${title(d.definition?.title||'Опросник',clinicalDraft?'Пилотная русская версия · только тестирование на вымышленных данных.':'Демонстрационная форма · без диагностической интерпретации.', '/patient/tasks')}${notice(d.definition?.disclaimer||'Невалидированная учебная форма.',true)}${card(`<form data-form="questionnaire" data-id="${attr(aid)}" data-revision="${attr(d.draft.revision)}" data-version="${attr(d.assignment.definition_version)}" class="form-stack">${questions.map((q,i)=>`<fieldset class="field bare-fieldset"><legend class="question-legend">${i+1}. ${esc(q.label)}</legend><div class="row">${(clinicalDraft?safeArray(q.options):safeArray(d.definition.options).map(n=>({value:n,label:String(n)}))).map(o=>`<label class="chip"><input type="radio" required data-answer="true" name="${attr(q.id)}" value="${attr(o.value)}" ${answers[q.id]===o.value?'checked':''}> ${esc(o.label)}</label>`).join('')}</div></fieldset>`).join('')}<p class="error-inline" data-form-error role="alert"></p><div class="row"><button type="button" class="btn btn-secondary" data-command="save-questionnaire">Сохранить черновик</button><button class="btn btn-primary">Отправить ответы</button></div></form>`)}`;
 }
 if(path==='/patient/trends'){
  const r=await err(()=>api.get(p+'/chart'));const period=app.period||30;
  return `${title('Моя динамика','Динамика отражает реальные записи вашего профиля, полученные от сервера.','/patient')}<div class="row space-bottom-20"><div class="segmented">${[7,30,90].map(n=>`<button data-period="${n}" class="${period===n?'active':''}" aria-pressed="${period===n}">${n} дней</button>`).join('')}</div></div>${r.error?protectedError(r.error):chartSeries(r.data.series,period)}`;
 }
 if(path==='/patient/treatment'||path==='/patient/treatment/adherence'){
  const r=await err(()=>api.get('/api/v1/p0/care-plans'));if(r.error)return title('Моё лечение')+protectedError(r.error);
  return `${title(path.endsWith('adherence')?'Дневник приёма':'Моё лечение','Только утверждённые и доступные вам планы.','/patient')}${card(list(r.data.items,p=>`<div class="stack"><h3>${esc(p.title||'План лечения')}</h3><span class="pill">${esc(status(p.status))}</span>${safeArray(p.items).map(i=>`<div class="list-row"><div class="row-main"><h4>${esc(i.title)}</h4><div class="small muted">${esc(i.frequency||'Режим не указан')}</div></div><button class="btn btn-secondary btn-sm" data-command="report-plan" data-id="${attr(i.id)}">Отметить</button></div>`).join('')}</div>`,'Активного плана пока нет','В этом разделе появятся только опубликованные врачом планы.'))}${path==='/patient/treatment'?link('/patient/treatment/adherence','Дневник выполнения','secondary','calendar'):''}`;
 }
 if(path==='/patient/adverse-events/new')return `${title('Сообщить о возможном нежелательном явлении','Ваше сообщение не определяет причинную связь; оценку выполняет специалист.','/patient/treatment')}${card(`<form data-form="adverse" class="form-stack"><div class="field"><label for="adverse-description">Опишите событие</label><textarea id="adverse-description" name="description" maxlength="2000" required placeholder="Что произошло и когда вы это заметили?"></textarea></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Отправить сообщение</button></form>`)}`;
 if(path==='/patient/appointments'||path==='/patient/appointments/new'){
  if(path.endsWith('/new'))return `${title('Запросить приём','Если нет действующей связи, начните с первичного обращения.','/patient/appointments')}${card(`${notice('Выберите врача и создайте первичное обращение. Приём предложит врач в рамках обращения.')} ${link('/doctors','Выбрать врача','primary','search')}`)}`;
  const r=await err(()=>api.get('/api/v1/appointments'));return `${title('Мои приёмы','Предложения времени и подтверждённые записи.','/patient')}${r.error?protectedError(r.error):card(list(r.data.items,a=>`<div class="list-row"><div class="row-main"><h4>${esc(compactTime(a.proposed_at))}</h4><div class="sub">${esc(a.format||'Формат не указан')} · ${esc(status(a.status))}</div></div>${a.status==='offered'?`<button class="btn btn-primary btn-sm" data-command="confirm-appointment" data-id="${attr(a.id)}">Подтвердить</button>`:''}</div>`,'Приёмов пока нет'))}<div class="row space-top-18">${link('/patient/appointments/new','Запросить приём','primary','plus')}</div>`;
 }
 if(path==='/patient/specialists/find')return `<div>${title('Найти специалиста','', '/patient/specialists')}${link('/doctors','В каталог','primary','search')}</div>`;
 if(path==='/patient/specialists'){
  const r=await err(()=>api.get('/api/v1/patients/me/links'));return title('Мои специалисты','Подтверждённые клинические связи.', '/patient')+(r.error?protectedError(r.error):card(list(r.data.items,l=>row(l.display_name||l.doctor_name||'Специалист',l.specialty||'',`/doctors/${segment(l.doctor_id||l.id)}`),'Нет активных связей')));
 }
 if(path==='/patient/access'||path==='/patient/access/care-team'){
  const r=await err(()=>api.get('/api/v1/patient/care-team-visibility'));
  return `${title('Разрешения на данные','Сведения о видимости команды врачей и доступных согласиях.','/patient')}${r.error?protectedError(r.error):card(`${notice('Изменение видимости всегда требует явного подтверждения; отсутствие записей не доказывает наличие согласий.')} ${list(r.data.items,i=>row(`${i.doctor_a} · ${i.doctor_b}`,i.active?'Видимость активна':'Видимость отключена'), 'Разрешений на видимость нет')}${link('/patient/admin-identity','Настроить ФИО для администрации клиники','secondary')}`)}`;
 }
 if(path==='/patient/admin-identity'){
  const results=await Promise.allSettled([api.get('/api/v1/admin-privacy/me/clinics'),api.get('/api/v1/admin-privacy/me/values')]);
  if(results.some(r=>r.status==='rejected'))return title('ФИО для администрации','', '/patient/access')+protectedError(results.find(r=>r.status==='rejected').reason);
  const clinics=safeArray(results[0].value.items),values=results[1].value.fields||{};
  return `${title('ФИО для администрации клиники','Предоставляется только по вашему отдельному разрешению.','/patient/access')}
  ${notice('Имя в профиле пациента не передаётся администрации автоматически. Здесь можно указать отдельные поля и выдать или отозвать разрешение.',true)}
  ${card(`<h2>Контактные сведения в защищённом хранилище</h2><form data-form="admin-identity-values" class="form-stack"><div class="field"><label>Фамилия</label><input name="last_name" value="${attr(values.last_name||'')}" maxlength="100" autocomplete="off"></div><div class="field"><label>Имя</label><input name="first_name" value="${attr(values.first_name||'')}" maxlength="100" autocomplete="off"></div><div class="field"><label>Отчество (если есть)</label><input name="middle_name" value="${attr(values.middle_name||'')}" maxlength="100" autocomplete="off"></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Сохранить ФИО в защищённом хранилище</button></form>`)}
  ${clinics.length?clinics.map(x=>card(`<h3>Организация: ${esc(x.organization_id)}</h3><p class="small muted">Существующая связь: ${x.relationship_active?'да':'нет'} · Модуль передачи полей: ${x.feature?.enabled?'включён':'не активирован администратором платформы'}</p><p class="small muted">Текущее разрешение: ${x.policy?.active?'активно':'не предоставлено'}</p>${safeArray(x.templates).length&&x.relationship_active?`<form class="form-stack" data-form="admin-identity-consent"><input type="hidden" name="organization_id" value="${attr(x.organization_id)}"><input type="hidden" name="revision" value="${attr(x.policy?.revision||0)}"><div class="field"><label>Шаблон разрешённых полей</label><select name="template_id" required>${safeArray(x.templates).map(t=>`<option value="${attr(t.id)}">${esc(t.template_key)} · версия ${esc(t.version)}: ${esc(t.read_fields.join(', '))}</option>`).join('')}</select></div><label class="checkline"><input type="checkbox" name="confirmed" required>Разрешаю администрации читать только указанные выше поля.</label><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Выдать разрешение</button></form>`:'<p>Необходимо создать шаблон разрешений у администратора платформы и подтвердить связь с клиникой.</p>'}${x.policy?.active?`<button type="button" class="btn btn-secondary" data-command="admin-identity-revoke" data-org="${attr(x.organization_id)}">Отозвать разрешение</button>`:''}`)).join(''):card(state('Связанных клиник нет','После принятия приглашения врача здесь появится организация и доступные шаблоны.'))}`;
 }
 if(path==='/patient/profile')return profilePage('patient');
 if(path==='/patient/requests'||path==='/patient/requests/new'||path.startsWith('/patient/requests/'))return requestPage(path,params,app,'patient');
 if(path==='/patient/messages'||path.startsWith('/patient/messages/'))return messagePage(path,params,app,'patient');
 if(path==='/patient/assistant'||path.startsWith('/patient/assistant/'))return assistantPage(path,app);
 if(path.startsWith('/patient/appointments/')&&path.endsWith('/visit'))return title('Комната консультации','', '/patient/appointments')+card(state('Видеосвязь не подтверждена','В этой версии сервер не предоставляет подтверждённую аудио- или видеокомнату. Не пытайтесь подключаться через фиктивную кнопку.'));
 if(path.startsWith('/patient/reviews/'))return title('Отзыв после приёма','', '/patient/appointments')+card(state('Публикация отзыва недоступна','Backend не предоставляет подтверждённого обработчика создания отзыва.'));
 return null;
}
export async function requestPage(path,params,app,role){
 if(path.endsWith('/new')){
  const r=await err(()=>api.get('/api/v1/public/doctors'));
  const linked=app.session?.context?.role==='patient'?await err(()=>api.get('/api/v1/patients/me/links')):{data:{items:[]}};
  const doctors=[...safeArray(r.data?.items)];
  for(const d of safeArray(linked.data?.items))if(!doctors.some(x=>x.id===d.id))doctors.push({...d,name:d.display_name});
  const selected=new URLSearchParams((location.hash||'').split('?')[1]||'').get('doctor');
  return `${title('Новое обращение','Анкета первого обращения передаётся выбранному врачу отдельно от переписки.', '/patient/requests')}
  ${!doctors.length?notice('Доступных специалистов пока нет. Примите приглашение врача или выберите опубликованный профиль в каталоге.')+link('/invite/accept','Принять приглашение','secondary'):''}
  ${card(`<form data-form="new-request" class="form-stack"><div class="field"><label for="req-doctor">Специалист</label><select id="req-doctor" required name="doctor_id"><option value="">Выберите специалиста</option>${doctors.map(d=>`<option value="${attr(d.id)}" ${selected===d.id?'selected':''}>${esc(d.name)} · ${esc(d.specialty||'')}</option>`).join('')}</select></div><div class="field"><label for="req-intake">Суть обращения</label><textarea id="req-intake" required name="text" maxlength="2000" placeholder="Опишите причину обращения своими словами"></textarea></div><label class="checkline"><input type="checkbox" name="case_consent" required><span>Я разрешаю показать выбранному врачу только сведения из этого обращения.</span></label><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Отправить обращение</button></form>`)}`;
 }
 const base=role==='patient'?'/patient/requests':'/doctor/requests',isChat=path.endsWith('/chat');
 if(path===base){const r=await err(()=>api.get('/api/v1/previsit-cases'));return `${title(role==='patient'?'Мои обращения':'Очередь обращений','Первичные обращения не создают автоматически долгосрочную клиническую связь.',role==='patient'?'/patient':'/doctor')}${r.error?protectedError(r.error):card(list(r.data.items,c=>row('Обращение · '+compactDate(c.created_at),'Статус: '+status(c.status),base+'/'+segment(c.id),'Открыть'),'Обращений пока нет'))}${role==='patient'?`<div class="row space-top-20">${link(base+'/new','Новое обращение','primary','plus')}</div>`:''}`;}
 const id=params.requestId;if(!id)return null;
 const r=await err(()=>api.get('/api/v1/previsit-cases/'+segment(id)));if(r.error)return title('Карточка обращения','',base)+protectedError(r.error);
 const c=r.data;
 if(isChat){const m=await err(()=>api.get('/api/v1/previsit-cases/'+segment(id)+'/messages'));
 return `${title('Переписка по обращению','Ответ врача может открыть возможность отправлять следующие сообщения.',base+'/'+segment(id))}${m.error?protectedError(m.error):card(`${messageThread(safeArray(m.data.items),app.session.user?.id)}<form data-form="case-message" data-id="${attr(id)}" class="form-stack space-top-18"><div class="field"><label for="case-message">Сообщение</label><textarea required maxlength="2000" name="text" id="case-message" placeholder="Напишите сообщение"></textarea></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">${icon('mail')} Отправить</button></form>${notice('Первое сообщение пациента ограничено сервером. До ответа врача повторная отправка может быть заблокирована.')}`)}`;}
 return `${title('Обращение','Статус: '+status(c.status),base)}${card(`<div class="row space-between"><div><h3>Анкета обращения</h3><p class="small muted">Создано ${esc(compactTime(c.created_at))}</p></div><span class="pill">${esc(status(c.status))}</span></div><div class="card inset"><p>${esc(c.intake?.text||'Текст не передан')}</p></div><div class="row space-top-20">${link(base+'/'+segment(id)+'/chat','Открыть переписку','primary','message')}${role==='doctor'&&c.status==='submitted'?`<button class="btn btn-secondary" data-command="review-request" data-id="${attr(id)}">Принять к рассмотрению</button>`:''}</div>`)}`+
 (role==='doctor'?card(`<h3>Предложить время</h3><p class="muted">Предложение подтверждается пациентом отдельно.</p><form data-form="offer" data-id="${attr(id)}" class="form-stack"><div class="field"><label for="offer-at">Дата и время</label><input type="datetime-local" name="proposed_at" id="offer-at" required></div><div class="field"><label for="offer-format">Формат</label><select name="format" id="offer-format"><option value="video">Онлайн (видео — возможность соединения не гарантирована)</option><option value="audio">Аудио (не проверено)</option><option value="in_person">Очно</option></select></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Предложить время</button></form>`):'');
}
function messageThread(messages,me){return `<div class="message-list">${messages.length?messages.map(m=>`<div class="bubble ${m.sender_id===me?'own':''}"><div>${esc(m.text||m.body||'')}</div><div class="meta">${m.sender_id===me?'Вы':'Собеседник'} · ${esc(compactTime(m.created_at))}</div></div>`).join(''):state('Нет сообщений','Напишите первое сообщение после создания обращения.')}</div>`;}
export async function messagePage(path,params,app,role){
 const base='/'+role+'/messages';
 if(path===base){const c=await err(()=>api.get('/api/v1/previsit-cases'));return `${title('Сообщения','Чаты первичных обращений и клиническая переписка имеют разные правила доступа.','/'+role)}${c.error?protectedError(c.error):card(list(c.data.items,v=>row('Диалог обращения',`От ${compactDate(v.created_at)} · ${status(v.status)}`,`/${role}/requests/${segment(v.id)}/chat`),'Диалогов пока нет','Здесь появятся чаты по доступным обращениям.'))}`;}
 const other=params.threadId;
 return title('Приватный диалог','Доступность сообщений проверяется сервером.',base)+card(state('Выберите доступный диалог','Для переписки откройте конкретное обращение из списка. Невозможно определить собеседника по непрозрачному ID маршрута.','empty',link(base,'К списку','primary')));
}
export async function doctorPage(path,params,app){
 if(app.session?.context?.role!=='doctor')return title('Требуется роль врача')+card(state('Доступ ограничен','Выберите разрешённый кабинет.','forbidden',link('/login','Войти')));
 if(path==='/doctor'){
  const r=await err(()=>api.get('/api/v1/doctor-experience/dashboard'));if(r.error)return title('Рабочий стол врача')+protectedError(r.error);
  const d=r.data;return `${title('Рабочий стол врача','Данные пациентов отображаются только в пределах подтверждённого доступа.')}
  <div class="columns three section">${[['patients','Пациенты','/doctor/patients'],['attention','Сигналы','/doctor/alerts'],['appointments','Приёмы','/doctor/appointments']].map(([key,l,to])=>{const v=d.counters?.[key];return `<a class="metric" href="/#${to}"><div class="label">${l}</div><div class="value">${typeof v==='number'?v:'—'}</div><span class="small">Открыть раздел ${icon('arrow',14)}</span></a>`}).join('')}</div><div class="dashboard-grid section"><div class="stack">${card(`<div class="row space-between"><h2>Приоритетные сигналы</h2>${link('/doctor/alerts','Все сигналы')}</div>${list(safeArray(d.warnings).slice(0,5),s=>row(s.patient_name||'Пациент',s.title||s.source||'',`/doctor/alerts/${segment(s.id)}`, 'Рассмотреть',s.status),'Нет доступных сигналов')}`)}${card(`<div class="row space-between"><h2>Первичные обращения</h2>${link('/doctor/requests','Очередь')}</div>${list(safeArray(d.cases).slice(0,5),c=>row(c.patient_name||'Обращение',compactDate(c.created_at),`/doctor/requests/${segment(c.id)}`),'Новых обращений нет')}`)}</div><div class="stack">${card(`<h3>Ближайшие приёмы</h3>${list(safeArray(d.appointments).slice(0,5),a=>row(a.patient_name||'Приём',compactTime(a.proposed_at),'/doctor/appointments'),'Приёмов пока нет')}`)}${card(`<h3>Рабочие разделы</h3>${nav.doctor.slice(1).map(([l,h])=>row(l,'',h)).join('')}`)}</div></div>`;
 }
 if(path==='/doctor/patients'){
  const r=await err(()=>api.get('/api/v1/doctors/me/patients'));return title('Мои пациенты','Только пациенты с подтверждёнными разрешениями.', '/doctor')+(r.error?protectedError(r.error):card(`<div class="search-tools"><input class="search-field" type="search" id="patient-search" placeholder="Поиск по имени" aria-label="Поиск пациентов"></div><div id="patient-list">${list(r.data.items,p=>row(p.display_name,`Приоритет: ${p.attention_level||'не указан'}`,`/doctor/patients/${segment(p.id)}`),'Пациентов нет')}</div>`));
 }
 if(path.startsWith('/doctor/patients/'))return doctorPatientPage(path,params,app);
 if(path==='/doctor/alerts'||path.startsWith('/doctor/alerts/')){
  const id=params.alertId;if(id){const r=await err(()=>api.get('/api/v1/doctor-experience/signals/'+segment(id)));return title('Оценка сигнала','Решение остаётся за врачом.','/doctor/alerts')+(r.error?protectedError(r.error):card(`${fields(r.data)}${notice('Оценка и эскалация доступны только при серверном подтверждении и применимых правилах.',true)}`));}
  const r=await err(()=>api.get('/api/v1/doctor-experience/signals'));return title('Сигналы','Автоматические наблюдения — не клинические назначения.', '/doctor')+(r.error?protectedError(r.error):card(list(r.data.items,a=>row(a.patient_name||'Сигнал',`${a.source||''} · ${status(a.status)}`,`/doctor/alerts/${segment(a.id)}`),'Активных сигналов нет')));
 }
 if(path==='/doctor/requests'||path.startsWith('/doctor/requests/'))return requestPage(path,params,app,'doctor');
 if(path==='/doctor/messages'||path.startsWith('/doctor/messages/'))return messagePage(path,params,app,'doctor');
 if(path==='/doctor/appointments'||path==='/doctor/calendar'){
  const r=await err(()=>api.get('/api/v1/appointments'));return title(path.endsWith('calendar')?'Расписание':'Запросы и записи','Подтверждённые сервером записи.', '/doctor')+(r.error?protectedError(r.error):card(list(r.data.items,a=>row('Приём',`${compactTime(a.proposed_at)} · ${status(a.status)}`),'Приёмов нет')));
 }
 if(path==='/doctor/questionnaires'||path==='/doctor/questionnaires/assign'){
  const r=await Promise.allSettled([api.get('/api/v1/patient-experience/questionnaires/definitions'),api.get('/api/v1/doctors/me/patients'),api.get('/api/v1/patient-experience/questionnaires/assignments')]);
  const defs=safeArray(r[0].value?.items),patients=safeArray(r[1].value?.items),assign=safeArray(r[2].value?.items);
  return `${title(path.endsWith('assign')?'Назначить опросник':'Опросники','Для демонстрации доступны технические формы и четыре пилотные версии клинических опросников.','/doctor')}${card(`<h3>Назначить опросник пациенту</h3>${notice('PHQ-9, PHQ-2, GAD-7 и GAD-2 пока не утверждены в данном приложении для клинического применения. Для тестирования используйте только вымышленные данные.',true)}<form data-form="assign-questionnaire" class="form-stack space-top-16"><div class="field"><label>Пациент</label><select name="patient_id" required><option value="">Выберите пациента</option>${patients.map(p=>`<option value="${attr(p.id)}">${esc(p.display_name)}</option>`).join('')}</select></div><div class="field"><label>Форма</label><select name="definition_id" required><option value="">Выберите опросник</option>${defs.map(d=>`<option value="${attr(d.id)}">${esc(d.title)}</option>`).join('')}</select></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary" ${!patients.length||!defs.length?'disabled':''}>Назначить</button></form>`)}`+
 card(`<h3>Назначенные опросники</h3>${list(assign,a=>`<div class="list-row"><div class="row-main"><h4>${esc(defs.find(d=>d.id===a.definition_id)?.title||a.definition_id)}</h4><div class="sub">${status(a.status)} · ${compactDate(a.created_at)}</div></div>${a.status==='submitted'?`<button type="button" class="btn btn-secondary btn-sm" data-command="doctor-questionnaire-result" data-id="${attr(a.id)}">Посмотреть результат</button>`:''}</div>`,'Назначений пока нет')}`);
 }
 if(path==='/doctor/invitations'||path==='/doctor/invitations/new'){
  const r=await err(()=>api.get('/api/v1/onboarding/invitations'));
  return `${title(path.endsWith('/new')?'Приглашение пациенту':'Приглашения пациентам','Врач указывает категории, доступ к которым пациент подтверждает отдельно.','/doctor')}${card(`<h3>Создать приглашение</h3><form data-form="create-invitation" class="form-stack"><div class="field"><label for="inv-email">Email получателя</label><input type="email" required name="recipient_email" id="inv-email" placeholder="patient@example.test"></div><fieldset class="bare-fieldset"><legend class="small muted">Категории доступа</legend><div class="row">${[['symptoms','Симптомы'],['diagnosis','Диагнозы'],['medications','Лекарства'],['severity','Выраженность']].map(([v,l])=>`<label class="checkline"><input type="checkbox" name="category" value="${v}">${l}</label>`).join('')}</div></fieldset><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Создать приглашение</button></form><div id="created-invitation"></div>`)}${r.error?protectedError(r.error):card(`<h3>Ранее созданные</h3>${list(r.data.items,a=>row('Приглашение',`${status(a.status)} · срок до ${compactDate(a.expires_at)}`),'Приглашений нет')}`)}`;
 }
 if(path==='/doctor/clinical-library')return catalogPage('/clinical-library');
 if(path==='/doctor/profile/edit')return profilePage('doctor');
 if(path==='/doctor/colleagues'||path.startsWith('/doctor/colleagues/')){
  if(path.endsWith('/shared-patients')){
   const r=await err(()=>api.get('/api/v1/doctors/'+segment(params.doctorId)+'/shared-patients'));
   return title('Общие пациенты','Только при индивидуальных согласиях.', '/doctor/colleagues')+(r.error?protectedError(r.error):card(list(r.data.items,p=>row(p.display_name||'Пациент','Согласованная связь',p.patient_id?`/doctor/patients/${segment(p.patient_id)}`:null),'Разрешённых общих пациентов нет')));
  }
  if(path.endsWith('/messages'))return colleagueChat(params.doctorId,app);
  const r=await err(()=>api.get('/api/v1/public/doctors'));return title('Коллеги','Переписка с коллегой сама по себе не предоставляет доступ к пациенту.', '/doctor')+(r.error?protectedError(r.error):card(list(r.data.items.filter(d=>d.id!==app.session.user.id),d=>`<div class="list-row"><div class="doctor-head row-main">${doctorImg(d)}<div><h4>${esc(d.name)}</h4><div class="sub">${esc(d.specialty||'')}</div></div></div><a class="btn btn-secondary btn-sm" href="/#/doctor/colleagues/${segment(d.id)}/messages">Написать</a><a class="btn btn-quiet btn-sm" href="/#/doctor/colleagues/${segment(d.id)}/shared-patients">Общие пациенты</a></div>`,'Коллеги не опубликованы')));
 }
 if(path==='/doctor/nlp-lab'||path==='/doctor/clinical-copilot'||path==='/doctor/import')return specializedDoctor(path,app);
 if(path==='/doctor/reviews')return title('Отзывы','Опубликованные отзывы без искусственного рейтинга.','/doctor')+card(state('Отзывов нет','В этом окружении нет подтверждённого API для списка отзывов врача.'));
 if(path.startsWith('/doctor/appointments/')&&path.endsWith('/visit'))return title('Консультация','', '/doctor/appointments')+card(state('Средство аудио- или видеосвязи не подтверждено','История приёмов остаётся доступна только через подтверждённые сервером функции.'));
 return null;
}
async function doctorPatientPage(path,params,app){const id=params.patientId;if(!id)return null;
 if(path.includes('/clinical-intelligence/chat/'))return chatView(path,false);
 if(path.endsWith('/clinical-intelligence'))return doctorClinicalCase(id);
 const base=`/doctor/patients/${segment(id)}`;
 const section=path.slice(base.length).replace(/^\//,'');const labels={'clinical-intelligence':'AI-разбор',trends:'Динамика',history:'Анамнез',treatment:'Лечение',psychotherapy:'Поведенческая терапия',visits:'История визитов','adverse-events':'Нежелательные явления',decisions:'Клинические решения',access:'Доступ'};
 const endpoints={
 '':'/api/v1/doctors/me/patients/:patientId/overview',
 trends:'/api/v1/patient-experience/physician/patients/:patientId/chart',
 history:'/api/v1/p0/history/:patientId',
 treatment:'/api/v1/doctors/me/patients/:patientId/clinical',
 visits:'/api/v1/p0/encounters/:patientId',
 'adverse-events':'/api/v1/p0/adverse-events?patient_id=:patientId',
 decisions:'/api/v1/p0/decisions/:patientId',access:'/api/v1/doctors/me/patients/:patientId/overview'};
 const name=labels[section]||'Карта пациента';const endpoint=endpoints[section];
 if(!endpoint)return title(name,'',base)+card(state('Сценарий не подключён','Сервер не предоставляет подтверждённую операцию для этого экрана.'));
 const r=await err(()=>api.get(apiPath(endpoint,{patientId:id})));if(r.error)return title(name,'', '/doctor/patients')+protectedError(r.error);
 const tabs=`<div class="row gap-sm space-bottom-18">${[['','Обзор'],...Object.entries(labels)].map(([slug,label])=>`<a class="chip ${section===slug?'selected':''}" href="/#${base}${slug?'/'+slug:''}">${esc(label)}</a>`).join('')}</div>`;
 const d=r.data;
 if(section==='trends')return title('Динамика пациента','Доступна только при разрешении на симптомы.', '/doctor/patients')+tabs+chartSeries(d.series||[]);
 return title(name,'Данные представлены только в пределах доступных серверных разрешений.', '/doctor/patients')+tabs+card(`<h3>${esc(name)}</h3>${safeArray(d.items).length?safeArray(d.items).map(x=>row(x.title||x.display_name||'Запись',x.description||x.status||compactDate(x.created_at))).join(''):fields(d)||state('Данных пока нет','У пациента нет доступных записей в этом разделе.')}`);
}
export async function colleagueChat(doctorId,app){const path='/api/v1/threads/doctor_peer/'+segment(doctorId)+'/messages',r=await err(()=>api.get(path));return `${title('Переписка с коллегой','Не предоставляет доступа к медицинской карте.','/doctor/colleagues')}${r.error?protectedError(r.error):card(`${messageThread(r.data.items||[],app.session.user.id)}<form data-form="peer-message" data-id="${attr(doctorId)}" class="form-stack"><div class="field"><label>Сообщение</label><textarea name="text" maxlength="2000" required></textarea></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Отправить сообщение</button></form>`)}`;}
async function specializedDoctor(path,app){
 if(path==='/doctor/nlp-lab')return `${title('Лаборатория NLP','Только синтетический текст без идентифицирующих сведений.','/doctor')}${card(`<form data-form="nlp" class="form-stack"><div class="field"><label for="synthetic-note">Учебный синтетический текст</label><textarea id="synthetic-note" name="text" maxlength="10000" required placeholder="Введите только явно синтетические сведения">Вымышленный пациент: тревожность последние дни, плохо сплю, трудно концентрироваться на работе. Хочу обсудить это с врачом.</textarea></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Извлечь сведения</button></form><div id="nlp-result"></div>`)}`;
 if(path==='/doctor/import')return title('Импорт синтетической выписки','', '/doctor')+card(state('Серверный импорт не подтверждён','Не загружайте реальные медицинские документы.'));
 return doctorClinicalHub();
}
export async function profilePage(role){const r=await err(()=>api.get('/api/v1/profiles/me'));
 if(r.error)return title('Мой профиль','',role==='doctor'?'/doctor':'/patient')+protectedError(r.error);const p=r.data;
 return `${title('Мой профиль','Сведения сохраняются только после подтверждения сервера.',role==='doctor'?'/doctor':'/patient')}
 <div class="dashboard-grid"><section class="card"><form data-form="profile" data-revision="${attr(p.revision)}" class="form-stack"><div class="field"><label for="p-name">Имя</label><input id="p-name" name="display_name" required minlength="2" maxlength="100" value="${attr(p.display_name||'')}"></div><div class="field"><label for="p-bio">О себе</label><textarea id="p-bio" name="bio" maxlength="1000" placeholder="Расскажите о себе">${esc(p.bio||'')}</textarea></div><div class="field"><label for="p-contact">Предпочтительная связь</label><select id="p-contact" name="contact_preference"><option value="in_app" ${p.contact_preference==='in_app'?'selected':''}>В приложении</option><option value="email" ${p.contact_preference==='email'?'selected':''}>По email</option><option value="none" ${p.contact_preference==='none'?'selected':''}>Не связываться</option></select></div>${role==='doctor'?`<div class="field"><label for="p-specialty">Отображаемая специальность</label><input id="p-specialty" name="specialty_label" maxlength="120" value="${attr(p.specialty_label||'')}"></div><label class="checkline"><input type="checkbox" name="public_visibility" ${p.public_visibility?'checked':''}><span>Запросить публикацию профиля (требуется дополнительное подтверждение)</span></label>`:''}<p class="error-inline" data-form-error role="alert"></p><button class="btn btn-primary">Сохранить изменения</button></form></section><aside class="stack">${card(`<h3>Статус</h3>${fields({роль:roleNames[role],публикация:p.publication_status||'—',редакция:p.revision})}`)}${card(`<h3>Фотография</h3><div class="row">${p.photo_url?`<img class="doctor-photo large" src="${attr(p.photo_url)}" alt="Фотография профиля">`:`<div class="doctor-avatar large">${esc(initials(p.display_name))}</div>`}</div><p class="muted small">Загрузка изображений зависит от режима сервера и проверки формата.</p><form data-form="photo" data-revision="${attr(p.revision)}"><div class="field"><label for="p-photo">Выберите JPEG, PNG или WebP</label><input type="file" id="p-photo" name="photo" accept="image/jpeg,image/png,image/webp" required></div><p class="error-inline" data-form-error role="alert"></p><button class="btn btn-secondary btn-sm">Загрузить фото</button></form>`)}${role==='patient'?card(`<h3>Мои опросники и результаты</h3><p class="small muted">Завершённые формы сохраняются сервером и доступны в разделе заданий после повторного входа.</p>${link('/patient/tasks','Открыть историю результатов','primary')}${link('/patient/admin-identity','ФИО для администрации','secondary')}`):''}${role==='doctor'?card(`${notice('Образование, сертификаты и публикации редактируются только через подтверждённые структуры API; произвольные заявления не публикуются автоматически.')}`):''}</aside></div>`;
}
// Catalog URLs are stable across search, paging and cross-links.
const catalogParams=()=>new URLSearchParams((location.hash||'').split('?')[1]||location.search.slice(1));
const catalogHref=(values={})=>'/clinical-library?'+new URLSearchParams(values).toString();
const externalReference=(entry)=>{
 const re=/(https:\/\/[^\s<>"']+)/g;
 return String(entry).split(re).map(part=>{
  if(!part.startsWith('https://'))return esc(part);
  const url=part.replace(/[),.;]+$/,'');
  try{const parsed=new URL(url);if(parsed.protocol!=='https:')return esc(part);return `<a href="${attr(url)}" target="_blank" rel="noopener noreferrer" class="reference-url">${esc(url)}</a>${esc(part.slice(url.length))}`;}catch{return esc(part);}
 }).join('');
};
export async function catalogPage(path){
 const params=catalogParams(),query=params.get('q')||'',kind=params.get('type')||'',page=Math.max(1,Math.min(100000,Number(params.get('page'))||1));
 const perPage=50;
 const response=await err(()=>api.get('/api/v1/clinical-catalog/search?q='+encodeURIComponent(query)+'&type='+encodeURIComponent(kind)+'&page='+page+'&per_page='+perPage));
 const total=response.data?.total||0, pages=Math.max(1,Math.ceil(total/perPage));
 const linked=d=>row(d.title,d.description||d.code||'',catalogHref({q:query,type:kind,page,item:d.kind+':'+d.id}));
 const pager=total>perPage?`<nav aria-label="Страницы справочника" class="row space-between space-top-20"><span class="small muted">Страница ${page} из ${pages} · показаны ${response.data.items.length} из ${total}</span><div class="row">${page>1?link(catalogHref({q:query,type:kind,page:page-1}),'Предыдущая'):''}${page<pages?link(catalogHref({q:query,type:kind,page:page+1}),'Следующая'):''}</div></nav>`:'';
 return `${title('Клинический справочник','Полный каталог диагнозов, препаратов, методов терапии и опросников. Сведения требуют проверки по актуальным источникам.')}${card(`<form class="search-tools" data-form="catalog-search"><div class="field grow"><label for="catalog-q">Поиск</label><input id="catalog-q" class="search-field" type="search" name="q" value="${attr(query)}" placeholder="Препарат, диагноз, метод или опросник"></div><div class="field"><label for="catalog-type">Раздел</label><select id="catalog-type" name="type"><option value="">Все категории</option>${[['diagnosis','Диагнозы'],['medicine','Лекарства'],['therapy','Терапия'],['instrument','Опросники']].map(([v,l])=>`<option value="${v}" ${kind===v?'selected':''}>${l}</option>`).join('')}</select></div><button class="btn btn-primary align-self-end">${icon('search')} Искать</button></form><p class="small muted">${response.error?'Не удалось обновить поиск':`Найдено: ${esc(total)} · Версия: ${esc(response.data.source_version)}`}</p>${response.error?errorState(response.error):list(response.data.items,linked,'Совпадений нет','Попробуйте изменить запрос.')} ${pager}`)}`+
 (params.has('item')?'<div id="catalog-detail" class="space-top-20" aria-live="polite"></div>':'');
}
export async function catalogDetail(kind,id){
 const r=await err(()=>api.get('/api/v1/clinical-catalog/'+segment(kind)+'/'+segment(id)));
 if(r.error)return protectedError(r.error);
 const d=r.data;
 const sections=safeArray(d.reference_sections).map((section,i)=>`<section class="reference-section"><h3>${esc(section.title)}</h3>${safeArray(section.items).map(v=>`<p class="reference-line">${externalReference(v)}</p>`).join('')}</section>`).join('');
 const links=safeArray(d.links).length?`<div class="reference-section"><h3>Связанные материалы</h3>${safeArray(d.links).map(l=>row(l.title,({diagnosis:'Диагноз',medicine:'Препарат',therapy:'Метод терапии',instrument:'Опросник'})[l.kind]||l.kind,catalogHref({item:l.kind+':'+l.id}))).join('')}</div>`:'';
 const actions=d.kind==='instrument'&&['phq_9','phq_2','gad_7','gad_2'].includes(d.id)?`<div class="row">${link('/patient/tasks','Пройти пилотную форму в кабинете пациента','primary')}</div>`:'';
 const close=link(catalogHref({q:catalogParams().get('q')||'',type:catalogParams().get('type')||'',page:catalogParams().get('page')||1}),'Закрыть карточку');
 return card(`<div class="row space-between"><div><p class="eyebrow">${esc(d.kind||'Справочник')} · ${esc(d.source_version||'')}</p><h2>${esc(d.title)}</h2><p class="muted">${esc(d.code||d.id||'')}</p></div><span class="pill">Справочный материал</span></div>${d.reference_warning?notice(d.reference_warning,true):''}${d.license_note?notice(d.license_note,true):''}<p>${esc(d.description||'')}</p>${actions}${sections}${links}<div class="space-top-20">${close}</div>`);
}
export async function notificationPage(){const r=await err(()=>api.get('/api/v1/p0/notifications'));
 return `${title('Уведомления','Только события, доступные вашей роли.')}${r.error?protectedError(r.error):card(list(r.data.items,n=>`<div class="list-row"><div class="row-main"><h4>${esc(n.text||n.message||'Уведомление')}</h4><div class="sub">${esc(compactTime(n.created_at))} · ${esc(n.category||'')}</div></div>${n.href&&n.href.startsWith('/')?link(n.href,'Перейти'):''}${!n.read_at?`<button class="btn btn-quiet btn-sm" data-command="read-notice" data-id="${attr(n.id)}">Прочитано</button>`:''}</div>`,'Новых уведомлений нет'))}`;
}
function adminFullName(entry){
 const f=entry?.fields||{};
 const result=[f.last_name,f.first_name,f.middle_name].filter(x=>typeof x==='string'&&x.trim()).join(' ').trim();
 return result || 'ФИО скрыто: нет разрешения пациента';
}
function adminIdentity(entry){
 const name=adminFullName(entry);
 return `<div class="list-row"><span class="small muted">ФИО</span><strong>${esc(name)}</strong></div><p class="small muted">Доступ только к полям, разрешённым пациентом. Клиническая карта не раскрывается.</p>`;
}
export async function clinicPage(path,params,app){const role=app.session?.context?.role;if(!['clinic_admin','platform_admin'].includes(role))return title('Доступ ограничен')+card(state('Нужна роль администратора','Этот экран нельзя открыть без соответствующих полномочий.','forbidden'));
 const endpoints={'/clinic/patients':'/api/v1/p0/clinic/patients','/clinic/appointments':'/api/v1/p0/clinic/appointments','/clinic/staff':'/api/v1/p1/clinic/staff','/clinic/audit':'/api/v1/audit/me','/clinic/access-templates':'/api/v1/admin-privacy/templates','/clinic/invitations':'/api/v1/staff-enrollment/invitations','/clinic/licenses':'/api/v1/staff-enrollment/capabilities'};
 const names={'/clinic/patients':'Пациенты клиники','/clinic/appointments':'Очередь записи','/clinic/staff':'Сотрудники','/clinic/audit':'Журнал действий','/clinic/access-templates':'Шаблоны доступа','/clinic/invitations':'Приглашения сотрудников','/clinic/licenses':'Лицензии и места'};
 if(path==='/clinic')return `${title('Администрирование клиники','Организационные сведения не раскрывают закрытые клинические данные.')} ${cards(nav.clinic_admin.slice(1),([label,to,ico])=>tile(label,'Открыть административный раздел.',to,ico))}`;
 if(path.startsWith('/clinic/patients/')&&params.patientRef){const r=await err(()=>api.get('/api/v1/p0/clinic/patients/'+segment(params.patientRef)));return title('Административная карточка','', '/clinic/patients')+(r.error?protectedError(r.error):card(adminIdentity(r.data)+`<p class="small muted">Код записи: ${esc(r.data.patient_ref||'')}</p>`))}
 const url=endpoints[path];if(!url)return null;const r=await err(()=>api.get(url));
 const invitationGate=path==='/clinic/invitations'&&r.error?.status===403?card(`${notice('Приглашение сотрудников требует настроенного OIDC/MFA в synthetic_dev. Локальный Evaluation Sandbox не выдаёт профессиональные полномочия и не обходит эту проверку.',true)}${link('/clinic/staff','Открыть действующий штат','primary')}`):'';
 return `${title(names[path]||'Клиника','Только данные в пределах серверного административного доступа.','/clinic')}${invitationGate}${r.error?protectedError(r.error):card(safeArray(r.data.items).length?safeArray(r.data.items).map(x=>row(path==='/clinic/patients'?adminFullName(x):(x.display_name||x.name||x.user_ref||x.text||x.id||'Запись'),path==='/clinic/patients'?'Разрешённые организационные сведения':(x.specialty||x.status||x.role||x.created_at||''),path==='/clinic/patients'&&x.patient_ref?'/clinic/patients/'+segment(x.patient_ref):null)).join(''):fields(r.data)||state('Записей нет','Новых доступных данных пока нет.'))}`;
}
export async function researchPage(path,params,app){if(app.session?.context?.role!=='researcher')return title('Доступ ограничен')+card(state('Нужна роль исследователя','Эта аналитика предназначена для разрешённого синтетического контура.','forbidden'));
 if(path==='/research/demo-v3'){
  const cohort=new URLSearchParams(location.hash.split('?')[1]||'').get('cohort')||'';
  const base='/api/v1/research/demo-datasets/synthetic_research_v3';
  const [index,summary]=await Promise.all([err(()=>api.get('/api/v1/research/demo-datasets')),err(()=>api.get(base+'/summary?cohort='+encodeURIComponent(cohort)))]);
  let body=title('Синтетические исследования','Независимый учебный набор, не связанный с медицинскими картами.','/research')+notice('Вымышленные наблюдения. Эти агрегаты не являются клиническими доказательствами.',true);
  if(index.error||summary.error)return body+protectedError(index.error||summary.error)+link('/research/demo-v3','Открыть весь учебный набор','primary');
  const d=index.data.items[0],s=summary.data;
  body+=card(`<h2>${esc(d.title)}</h2><p>${esc(d.description)}</p><p class="small muted">Версия ${esc(d.version)} · ${esc(d.subjects_count)} вымышленных участников · ${esc(d.row_count)} наблюдений</p><form data-form="research-synthetic-filter" class="search-tools"><div class="field grow"><label for="research-cohort">Учебная группа</label><select name="cohort" id="research-cohort"><option value="">Все наблюдения</option><option value="A" ${cohort==='A'?'selected':''}>Группа A</option><option value="B" ${cohort==='B'?'selected':''}>Группа B</option></select></div><button class="btn btn-primary align-self-end">Рассчитать</button></form>`);
  body+=card(`<h2>Результат запроса</h2>${s.suppressed?notice('Недостаточно наблюдений: значения скрыты.'):fields({группа:cohort||'Все',наблюдений:s.n,заполнено:s.observed_n,пропусков:s.missing_n,'среднее (1–5)':s.mean})}<h3>Методика и ограничения</h3><p>Единица анализа: ${esc(s.unit_of_analysis)}. Формула: <code>${esc(s.formula)}</code>. Пропуски исключаются из среднего и учитываются отдельно.</p><p>Минимальный размер ячейки: ${esc(d.min_cell)}. Фильтрация по датам отключена для защиты малых ячеек.</p><p>${esc(s.limitations)}</p><div class="row"><a class="btn btn-secondary" href="${base}/export" download>Скачать CSV всех агрегатов</a>${link('/research','К разделам исследователя','secondary')}</div><p class="small muted">CSV содержит только общий агрегат всего набора. Фильтр группы не применяется к экспорту.</p>`);
  return body;
 }
 const urls={'/research/datasets':'/api/v1/research-workflow/sources','/research/cohorts':'/api/v1/research-workflow/definitions','/research/compare':'/api/v1/research/cohorts','/research/signals':'/api/v1/research/synthetic-summary','/research/exports':'/api/v1/research-workflow/definitions','/research/demo-v3':'/api/v1/research/demo-datasets'};
 if(path==='/research')return `${title('Исследовательская аналитика','Синтетические наборы без данных реальных пациентов.')} ${notice('Аналитика используется в учебном контуре. Нельзя интерпретировать результаты как клиническое доказательство.',true)}<div class="columns three space-top-18">${nav.researcher.slice(1).map(([l,p,i])=>tile(l,'Агрегаты и учебные материалы.',p,i)).join('')}</div>`;
 if(path.startsWith('/research/cases/'))return title('Учебный мини-кейс','', '/research')+card(state('Серверный кейс не подтверждён','Реальный эндпоинт по идентификатору учебного кейса не найден.'));
 const endpoint=urls[path];if(!endpoint)return null;const r=await err(()=>api.get(endpoint));
 const demoPath=card(`${r.error?notice('Для этого исследования требуется отдельный действующий грант доступа и подготовленный набор. Разрешения не создаются автоматически.',true):''}${link('/research/demo-v3','Открыть независимый учебный набор, фильтр и CSV','primary')}`);
 return `${title(({datasets:'Доступные датасеты',cohorts:'Конструктор когорт',compare:'Сравнение групп',signals:'Наблюдаемые сигналы',exports:'Экспорт агрегатов','demo-v3':'Синтетические исследования'})[path.split('/')[2]]||'Исследования','Сведения получены от исследовательских серверных маршрутов.','/research')}${demoPath}${r.error?protectedError(r.error):card(`<h3>Доступные наборы и определения</h3>${r.data.synthetic_only===true?notice('Только синтетические данные.'):''}${safeArray(r.data.items).length?safeArray(r.data.items).map(o=>row(o.title||o.name||o.id||'Набор',o.description||o.version||o.study_id||'',null)).join(''):fields(r.data)||state('Нет доступных данных','Проверьте разрешения исследовательского набора.')}`)}`;
}
export async function assistantPage(path,app){
 if(path.startsWith('/patient/assistant/thread/'))return chatView(path,true);
 if(path.startsWith('/patient/assistant/share/'))return `${title('Поделиться сводкой','Отправка требует отдельного согласия.','/patient/assistant')}${card(`${notice('Личный AI-чат не раскрывается врачу автоматически. Подготовка и передача сводки должны быть подтверждены пациентом; этот отдельный механизм пока не подключён.')}${link('/patient/assistant','Вернуться в AI-чат','primary')}`)}`;
 return patientAssistant();
}
const genericApi={
 '/doctor/patients/:patientId/psychotherapy':null,
 '/doctor/clinical-library/:articleId':'/api/v1/p0/reference-articles/:articleId',
 '/doctor/alerts/:alertId':'/api/v1/doctor-experience/signals/:alertId',
 '/clinic/patients/:patientRef':'/api/v1/p0/clinic/patients/:patientRef'
};
export async function genericPage(route,params){
 const endpoint=genericApi[route.path];
 if(endpoint){const r=await err(()=>api.get(apiPath(endpoint,params)));return title(route.title,route.action)+ (r.error?protectedError(r.error):card(fields(r.data)||state('Сведений пока нет','Сервер не вернул видимых полей.')));}
 return `${title(route.title,route.action)}${card(state('Действие пока недоступно','Страница сохранена для совместимости маршрутов, но в актуальном backend не подтверждён безопасный интеграционный сценарий для заявленного действия. Данные не сохраняются и не подменяются имитацией.'))}`;
}
export async function resolveView(route,path,params,app){
 if(path==='/')return landing(app);
 if(path==='/assessments'||path.startsWith('/assessments/'))return guestPage(path,app);
 if(path==='/login'||path.startsWith('/register'))return authPage(path,app);
 if(path==='/invite/accept'||path.startsWith('/invite/'))return invitationPage(params.token,app);
 if(path.startsWith('/doctors'))return publicDoctors(path,params,app);
 if(path==='/clinical-library')return catalogPage(path);
 if(path==='/notifications')return notificationPage();
 if(path==='/settings')return title('Настройки')+card(`${notice('Настройки интерфейса доступны через окно аккаунта.')} ${button('Открыть настройки','settings','primary')}`);
 if(path==='/onboarding')return title('Первоначальная настройка','', '/patient')+card(`${notice('Состояние первоначальной настройки контролируется сервером.')} ${link('/patient/profile','Заполнить профиль','primary')}`);
 if(path.startsWith('/patient'))return (await patientPage(path,params,app))??genericPage(route,params);
 if(path.startsWith('/doctor'))return (await doctorPage(path,params,app))??genericPage(route,params);
 if(path.startsWith('/clinic'))return (await clinicPage(path,params,app))??genericPage(route,params);
 if(path.startsWith('/research'))return (await researchPage(path,params,app))??genericPage(route,params);
 if(path.startsWith('/demo')){
  const actors=[
   ['Пациент',[['Гостевое прохождение 4 шкал','/assessments','Работает в учебном режиме'],['Задания и история результатов','/patient/tasks','Нужен вход'],['Дневник самочувствия','/patient','Нужен вход'],['AI-помощник Qwen','/patient/assistant','Требует Ollama + разрешения'],['Обращение и диалог с врачом','/patient/requests','Нужен вход и врач'],['Согласие на показ ФИО клинике','/patient/admin-identity','Отдельное согласие'],['Профиль','/patient/profile','Нужен вход']]],
   ['Врач',[['Рабочий стол','/doctor','Нужен аккаунт врача'],['Пациенты и карта','/doctor/patients','Требуется связь'],['Опросники и результаты','/doctor/questionnaires','Требуется связь'],['Clinical Intelligence: пример и анализ','/doctor/clinical-copilot','Qwen + данные обращения'],['NLP-лаборатория','/doctor/nlp-lab','Учебный серверный запрос'],['Консультации и обращения','/doctor/requests','Требуются тестовые записи'],['Clinical Catalog','/doctor/clinical-library','Просмотр материалов']]],
   ['Исследователь',[['Доступные датасеты','/research/datasets','Реальное чтение API'],['Демонстрационные исследования','/research/demo-v3','Учебные наборы'],['Конструктор когорт','/research/cohorts','Частично подключено'],['Сравнение групп','/research/compare','Частично подключено'],['Наблюдаемые сигналы','/research/signals','Частично подключено'],['Экспорт','/research/exports','UI прототип, нет готового экспорта']]],
   ['Администратор клиники',[['Организация','/clinic','Нужен clinic_admin'],['Пациенты и согласованные ФИО','/clinic/patients','Пациент должен выдать разрешение'],['Сотрудники и ФИО','/clinic/staff','Организационный список'],['Запись','/clinic/appointments','Административные сведения'],['Шаблоны доступа','/clinic/access-templates','Просмотр настроек'],['Организационные приглашения','/clinic/invitations','Частично подключено'],['Журнал','/clinic/audit','Частичное покрытие']]]
  ];
  return `${title('Демонстрация всех четырёх ролей','Выберите действие. Списки включают работающие сценарии и явно обозначенные экспериментальные экраны.')}${notice('Войдите под аккаунтом соответствующей роли. Доступ к данным не переключается одной кнопкой и не обходит серверные согласия.',true)}<div class="columns two">${actors.map(([name,items])=>card(`<h2>${esc(name)}</h2>${items.map(([label,href,description])=>row(label,description,href,'Открыть')).join('')}`)).join('')}</div>`;
 }
 if(path==='/api-lab.html')return title('Диагностические инструменты')+card(state('Не входит в пользовательский интерфейс','Этот внутренний инструмент не перенесён в обычную навигацию по соображениям разграничения доступа.'));
 return route?genericPage(route,params):title('Страница не найдена')+card(state('Неизвестный адрес','Проверьте ссылку или вернитесь на главную.','error',link('/','На главную','primary')));
}
